insert into public.admin_todos (id, title, notes, created_by, created_at) values
  ('7d0d0000-0000-4000-8000-000000000001', 'Make files downloadable', 'PdfViewer''s download link doesn''t force a download for cross-origin signed URLs. Needs a download-signed URL from getSignedResourceUrl, for every file kind, on the song page and the resources panel. (TODO.md #1)', null, timestamptz '2026-10-29T12:00:00Z'),
  ('7d0d0000-0000-4000-8000-000000000002', 'Transpose a chord chart up or down by a full key, with sharp or flat spelling', 'Charts are stored only as PDFs, which can''t be transposed. Needs charts stored as text (e.g. ChordPro) plus a parser and renderer; first chords could be transposed sooner. To decide: any target key or a fixed step? Save a transposed chart as a new key? (TODO.md #2)', null, timestamptz '2026-10-29T12:00:00Z'),
  ('7d0d0000-0000-4000-8000-000000000003', 'Make each key section collapsible when editing a song; collapse all but the primary key on load', 'Applies to MusicalSection and ResourcesSection on /songs/[id]/edit. A new song with one key starts expanded. Decide whether the Projection block counts as a key section. (TODO.md #3)', null, timestamptz '2026-10-29T12:00:00Z'),
  ('7d0d0000-0000-4000-8000-000000000004', 'Add lyrics and files in the same pass when creating a song', 'Lyrics are already part of the combined song form at /songs/new; files are not, because ResourcesSection needs a saved song ("Save to add files"). A nested or two-step flow may be what''s wanted. (TODO.md #4)', null, timestamptz '2026-10-29T12:00:00Z'),
  ('7d0d0000-0000-4000-8000-000000000006', 'Print from the app', 'Likely targets: a setlist as a one-page running order (key, BPM, energy), a song''s lyrics in arrangement order, and sheet music PDFs. To decide: which of these, and whether printing a setlist includes each song''s lyrics or sheet music. (TODO.md #6)', null, timestamptz '2026-10-30T12:00:00Z'),
  ('7d0d0000-0000-4000-8000-000000000007', 'Make "POP" a swappable module so the app can be open sourced for any Christian community', 'POP shows up in branding and colours, the "POP member" composer flag, branch names and seed data, the theme vocabulary and SSO. Likely approach: one community config (name, logo, colours, member and branch labels, features on or off). Also needs a LICENSE, a self-host guide and a licensing note. Cheaper the earlier it''s decided. (TODO.md #7)', null, timestamptz '2026-10-30T12:00:00Z'),
  ('7d0d0000-0000-4000-8000-000000000008', 'Create a setlist or playlist for a different branch, and filter lists by branch', 'Example: a Servant Branch musician playing in Portland sets Portland as the list''s branch. Owner decisions: any approved user may pick any branch; that branch''s music leaders may edit; it counts toward that branch''s usage. Needs an RLS migration, a branch picker in CreateListDialog and a branch filter on Open Setlist / Open Playlist. (TODO.md #8)', null, timestamptz '2026-11-03T12:00:00Z'),
  ('7d0d0000-0000-4000-8000-000000000010', 'Set player follow-ups: chords over the lyrics, and a leader''s screen moving everyone else''s', 'Chords over the lyrics needs songs stored as ChordPro text (a migration, parser, renderer and editor; it also unlocks transposing). Leader-driven paging needs a Supabase Realtime channel per setlist and a decision on who may lead. Both were left out of LIST-11. (TODO.md #10)', null, timestamptz '2026-11-03T12:00:00Z')
